/* Source: https://static.shuffle.dev/uploads/files/1c/1cfd603481e0a783afbce241c8651660967dc110/global-65710.js?v=1779579029 */
(function() {
  const init = () => {
    // Mobile menu toggle
    document.querySelectorAll('.mobile-menu-toggle').forEach(btn => {
      btn.addEventListener('click', () => {
        const nav = btn.closest('nav');
        const menu = nav.querySelector('.mobile-menu');
        if (menu) {
          menu.classList.toggle('hidden');
        }
      });
    });

    // Scroll reveal for game cards
    const cards = document.querySelectorAll('#games .group, #games [class*="border-dashed"]');
    cards.forEach((card, i) => {
      card.style.opacity = '0';
      card.style.transform = 'translateY(24px)';
      card.style.transition = 'opacity 0.5s ease, transform 0.5s ease';
      card.style.transitionDelay = (i * 80) + 'ms';
    });

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.style.opacity = '1';
          entry.target.style.transform = 'translateY(0)';
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1 });

    cards.forEach(card => observer.observe(card));

    // Scroll reveal for stat boxes
    const stats = document.querySelectorAll('#about .bg-zinc-900\\/60');
    stats.forEach((stat, i) => {
      stat.style.opacity = '0';
      stat.style.transform = 'translateY(20px)';
      stat.style.transition = 'opacity 0.5s ease, transform 0.5s ease';
      stat.style.transitionDelay = (i * 100) + 'ms';
    });

    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.style.opacity = '1';
          entry.target.style.transform = 'translateY(0)';
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15 });

    stats.forEach(stat => statsObserver.observe(stat));
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
